-- 20260823000004_drug_commercial_products_seed.sql
-- PKO-PERSISTENT-001 — Seed data for Produk Komersial Obat
--
-- Migrates existing hardcoded data from src/data/produkKomersialObatData.ts
-- into the new drug_brands and drug_commercial_products tables.
--
-- UUIDs are preserved from the original hardcoded data to maintain compatibility
-- with existing references in stok_obat.notes/metadata.
--
-- 13 brands, 363 products (all existing data, no dummy/internet data).

-- master_obat_uuid stores legacy string identifiers from in-memory obatData.ts
-- that are not always valid PostgreSQL UUIDs. Change column to text so the seed
-- can load without violating the uuid type constraint.
ALTER TABLE drug_commercial_products
  ALTER COLUMN master_obat_uuid TYPE text USING master_obat_uuid::text;

