  ('9a49fd42-e80a-4b90-90d7-5802018f8124', 'oxytet-la-fertilife', 'e15ef2da-a128-4dde-8528-4dae8d00e14b', 'a1b2c3d4-0001-4000-8000-000000000001', 'Oxytet LA Fertilife', 'Fertioxy LA 200', 'Injeksi', '250 mL', 'aktif', 'Oxytetracycline hydrochloride', '200 mg/mL (long-acting)', 'Indonesia', 'Simpan di tempat sejuk dan kering (15–25°C), terlindungi dari cahaya langsung. Setelah dibuka, gunakan dalam 28 hari.', 'PT Fertilife Indonesia', NULL, NULL, NULL, 'Oksitetrasiklin 200 mg/mL long-acting injeksi. Antibiotik spektrum luas untuk BRD, pasteurellosis, dan infeksi bakteri sistemik pada ruminansia.'),
